185	/// Build the plan from already-read sources plus MCP candidates discovered by
186	/// the existing external-import machinery (so server parsing stays single-sourced).
187	pub(crate) fn build_plan(
188	    sources: Vec<(PathBuf, SourceStatus)>,
189	    claude: Option<Value>,
190	    settings: Option<Value>,
191	    home: &Path,
192	    mcp_candidates: Vec<McpCandidateLine>,
193	) -> ClaudeImportPlan {
194	    let mut plan = ClaudeImportPlan {
195	        sources,
196	        mcp_candidates,
197	        ..ClaudeImportPlan::default()
198	    };
199	    if let Some(claude) = claude.as_ref() {
200	        if let Some(projects) = claude.get("projects").and_then(Value::as_object) {
201	            for (path, project) in projects {
202	                if let Some(servers) = project.get("mcpServers").and_then(Value::as_object) {
203	                    for name in servers.keys() {
204	                        plan.per_project_mcp.push(format!("{name} (project {path})"));
205	                    }
206	                }
207	                if plan.claude_projects.len() < 8 {
208	                    plan.claude_projects.push(path.clone());
209	                }
210	            }
211	        }
212	    }
213	    if let Some(settings) = settings.as_ref() {
214	        if let Some(env) = settings.get("env").and_then(Value::as_object) {
215	            for (key, value) in env {
216	                if SAFE_ENV_KEYS.contains(&key.to_ascii_lowercase().as_str()) {
217	                    match safe_env_value(value) {
218	                        Some(text) => {
219	                            plan.env_safe.insert(key.clone(), text);
220	                        }
221	                        None => plan.env_skipped.push(format!("{key} (value not portable)")),
222	                    }
223	                } else {
224	                    plan.env_skipped.push(key.clone());
225	                }
226	            }
227	        }
228	        if let Some(permissions) = settings.get("permissions").and_then(Value::as_object) {
229	            plan.permissions_default_mode = permissions
230	                .get("defaultMode")
231	                .and_then(Value::as_str)
232	                .map(str::to_string);
233	            for (key, target) in [
234	                ("allow", &mut plan.permissions_allow),
235	                ("ask", &mut plan.permissions_ask),
236	                ("deny", &mut plan.permissions_deny),
237	            ] {
238	                if let Some(rules) = permissions.get(key).and_then(Value::as_array) {
239	                    for rule in rules {
240	                        if let Some(text) = rule.as_str() {
241	                            target.push(text.to_string());
242	                        }
243	                    }
244	                }
245	            }
246	        }
247	        if let Some(hooks) = settings.get("hooks").and_then(Value::as_object) {
248	            for (event, entries) in hooks {
249	                let count = entries.as_array().map_or(1, Vec::len);
250	                plan.hook_events.push(format!("{event} ({count})"));
251	            }
252	        }
253	    }
254	    plan.has_claude_md = home.join(".claude").join("CLAUDE.md").is_file();
255	    plan
256	}
