258	/// Claude `permissions.defaultMode` → the Codewhale approval-posture
259	/// recommendation (report text only; nothing is applied).
260	pub(crate) fn approval_posture_recommendation(mode: Option<&str>) -> &'static str {
261	    match mode {
262	        Some("acceptEdits") => "auto-review posture (/permissions) matches acceptEdits",
263	        Some("plan") => "plan mode matches Claude's plan default",
264	        Some("bypassPermissions") => {
265	            "Full Access (yolo) matches bypassPermissions — confirm you want it"
266	        }
267	        _ => "the default Ask posture matches Claude's default",
268	    }
269	}
270	
271	/// One-line migration guidance for a Claude permission rule.
272	pub(crate) fn permission_rule_guidance(rule: &str) -> String {
273	    let rule = rule.trim();
274	    if rule.starts_with("Bash(") {
275	        format!("{rule} → an execpolicy rule for that command family (/permissions)")
276	    } else if rule.starts_with("WebFetch(domain:") || rule.starts_with("WebSearch(") {
277	        format!("{rule} → a fetch/network rule for that host or surface")
278	    } else if rule.starts_with("mcp__") {
279	        format!("{rule} → enable that MCP tool in your mcp.json enabled_tools")
280	    } else if rule.starts_with("Read(") || rule.starts_with("Edit(") || rule.starts_with("Write(")
281	    {
282	        format!("{rule} → a path-scoped ask rule (reads stay workspace-bounded by default)")
283	    } else {
284	        format!("{rule} → review against /permissions before mapping")
285	    }
286	}
