288	/// The unapplied portable bundle document for the safe env entries. JSON is a
289	/// first-class bundle format (`config import` accepts `.json`), so the
290	/// generated file goes through the same strict parser as any hand-written one.
291	pub(crate) fn portable_bundle_json(plan: &ClaudeImportPlan) -> String {
292	    let global: BTreeMap<&str, &str> = plan
293	        .env_safe
294	        .iter()
295	        .map(|(k, v)| (k.as_str(), v.as_str()))
296	        .collect();
297	    serde_json::json!({
298	        "schema_version": 1,
299	        "kind": "codewhale.portable-config",
300	        "metadata": {
301	            "name": "claude-import",
302	            "generator": "codewhale /import-claude",
303	        },
304	        "global": global,
305	    })
306	    .to_string()
307	}
