309	/// Render the reviewable plan shown in the transcript.
310	pub(crate) fn render_plan(plan: &ClaudeImportPlan) -> String {
311	    use std::fmt::Write as _;
312	
313	    let mut out = String::new();
314	    out.push_str("Claude import plan (nothing is applied without its own consent):\n");
315	    for (path, status) in &plan.sources {
316	        let _ = writeln!(out, "  · {}", status.describe(path));
317	    }
318	    if !plan.mcp_candidates.is_empty() {
319	        out.push_str("\nMCP servers (apply each with `/mcp import <name> --approve`):\n");
320	        for candidate in &plan.mcp_candidates {
321	            let blocked = if candidate.hard_blocked { " [blocked]" } else { "" };
322	            let _ = writeln!(out, "  · {}{blocked} — {}", candidate.name, candidate.summary);
323	        }
324	    }
325	    if !plan.per_project_mcp.is_empty() {
326	        out.push_str("\nProject-scoped MCP servers (listed for provenance only):\n");
327	        for name in plan.per_project_mcp.iter().take(8) {
328	            let _ = writeln!(out, "  · {name}");
329	        }
330	    }
331	    if !plan.env_safe.is_empty() {
332	        out.push_str("\nSafe env settings proposed for the portable bundle:\n");
333	        for key in plan.env_safe.keys() {
334	            let _ = writeln!(out, "  · {key}");
335	        }
336	    }
337	    if !plan.env_skipped.is_empty() {
338	        out.push_str("\nEnv keys not imported (secret-shaped or unmapped; values never shown):\n");
339	        for key in plan.env_skipped.iter().take(12) {
340	            let _ = writeln!(out, "  · {key}");
341	        }
342	    }
343	    let _ = writeln!(
344	        out,
345	        "\nApproval posture: {}.",
346	        approval_posture_recommendation(plan.permissions_default_mode.as_deref())
347	    );
348	    for (label, rules) in [
349	        ("Allow", &plan.permissions_allow),
350	        ("Ask", &plan.permissions_ask),
351	        ("Deny", &plan.permissions_deny),
352	    ] {
353	        if !rules.is_empty() {
354	            let _ = writeln!(out, "\n{label} rules (map manually; not auto-applied):");
355	            for rule in rules.iter().take(8) {
356	                let _ = writeln!(out, "  · {}", permission_rule_guidance(rule));
357	            }
358	        }
359	    }
360	    if !plan.hook_events.is_empty() {
361	        out.push_str("\nHook events (map manually with /hooks):\n");
362	        for event in &plan.hook_events {
363	            let _ = writeln!(out, "  · {event}");
364	        }
365	    }
366	    if plan.has_claude_md {
367	        out.push_str("\nStanding instructions: ~/.claude/CLAUDE.md found — copy it to ~/.codewhale/instructions.md (or the repo's AGENTS.md) to carry it over.\n");
368	    }
369	    out
370	}
