372	/// The written follow-through report (markdown).
373	pub(crate) fn report_markdown(plan: &ClaudeImportPlan) -> String {
374	    let mut out = String::from("# Claude import report\n\nGenerated by `/import-claude`. Nothing was applied automatically.\n\n");
375	    out.push_str(&render_plan(plan));
376	    if !plan.env_safe.is_empty() {
377	        out.push_str("\n## Apply the portable bundle\n\nReview the generated bundle, then run:\n\n    codewhale config import <bundle path>\n\n");
378	    }
379	    out.push_str("\n## Manual follow-ups\n\n- MCP: `/mcp import <name> --approve` per server (consent is recorded).\n- Permissions: map rules in /permissions and execpolicy.\n- Hooks: re-create matching hooks with /hooks.\n- Paths: copy CLAUDE.md if you want those standing instructions.\n");
380	    out
381	}
